-- World History 1 final module. Run seed_worldhistory1_course.sql first. Safe to run more than once.

do $seed$
declare cid uuid;
begin
  select id into cid from public.courses where slug = 'world-history-1';
  if cid is null then raise exception 'Run the course file first'; end if;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 7, $j$Final Assessment: Historical Inquiry Project$j$, $j${"prompt": "Complete a historical inquiry project on one turning point from this course. Choose from: the fall of Constantinople, the Magna Carta, the Black Death, the rise of Mali under Mansa Musa, the printing press, the Reformation, the Columbian Exchange, the French Revolution or the Industrial Revolution. Write complete sentences and label each part. Proverbs 25:2 says, It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.\n\nPart 1: Question and Timeline. State a clear historical question about your turning point. Make a timeline of at least eight dates, marked BC or AD, that show the causes and effects.\nPart 2: Sources. Identify at least one primary source and one secondary source about your topic (a sample is acceptable if you cannot find a real one, and you must say it is a sample). Tell who made each, when, why, and what each leaves out.\nPart 3: Causes. Explain at least two long term causes and one immediate trigger.\nPart 4: Effects. Explain at least three effects on religion, government, economy, learning or daily life.\nPart 5: Competing Interpretations. Describe how two historians or viewpoints might disagree about your turning point and tell which argument you find stronger and why.\nPart 6: Identity and Connections. Tell how the turning point still shapes the world, your community or your own faith today, and connect it to another unit in this course.\nPart 7: Reflection. In at least 100 words, explain what this course taught you about God's rule over the times and seasons, honest use of evidence, and how to treat people of every nation with dignity. Use Daniel 2:21, which says, And he changeth the times and the seasons: he removeth kings, and setteth up kings: he giveth wisdom unto the wise, and knowledge to them that know understanding.", "rubric": "200 points. Part 1, question and timeline: 24 points. Part 2, sources: 30 points. Part 3, causes: 28 points. Part 4, effects: 30 points. Part 5, competing interpretations: 32 points. Part 6, identity and connections: 28 points. Part 7, reflection: 20 points. Clear organization and complete sentences: 8 points. A score of 140 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Final Assessment: Historical Inquiry Project$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 31, $j$Final Exam: World History 1$j$, $j${"questions": [{"q": "A source created during the time being studied is a:", "options": ["Secondary source", "Timeline", "Theory", "Primary source"]}, {"q": "Checking a source against other sources is called:", "options": ["Migration", "Conquest", "Corroboration", "Imitation"]}, {"q": "The Byzantine capital, built by Constantine, was:", "options": ["Rome", "Athens", "Alexandria", "Constantinople"]}, {"q": "The Great Schism of 1054 divided the Church into:", "options": ["Lutheran and Calvinist", "Jesuit and Benedictine", "Roman Catholic and Eastern Orthodox", "Sunni and Shia"]}, {"q": "The Islamic calendar begins with the:", "options": ["Founding of Baghdad", "Fall of Rome", "Hijra in 622", "Crusades"]}, {"q": "The Abbasid dynasty ruled from the capital of:", "options": ["Tours", "Damascus", "Baghdad", "Cairo"]}, {"q": "In feudalism, a lord gave land called a fief to a:", "options": ["Merchant", "Serf only", "Vassal", "Pope"]}, {"q": "The Magna Carta of 1215 helped establish that:", "options": ["Parliament is forbidden", "The king is under the law", "Peasants rule", "The Pope appoints kings"]}, {"q": "The Black Death of 1347 to 1351 was a:", "options": ["War between England and France", "Plague that killed a large share of Europe", "Council of the Church", "Religious schism"]}, {"q": "In Japan, the military ruler who held real power was the:", "options": ["Merchant", "Shogun", "Daimyo", "Priest"]}, {"q": "Mansa Musa, ruler of Mali, is known for his:", "options": ["Voyage to America", "Writing of the Ninety Five Theses", "Conquest of Constantinople", "Pilgrimage to Mecca in 1324"]}, {"q": "The Aztec capital Tenochtitlan was built:", "options": ["On an island in Lake Texcoco", "In the Andes", "On the Bosporus", "On the Niger River"]}, {"q": "The Inca recorded numbers and records using:", "options": ["Glyph books", "Quipu", "Clay tablets from Sumer", "Printed paper"]}, {"q": "Martin Luther began the Reformation in:", "options": ["1215", "1066", "1517", "1789"]}, {"q": "The printing press with movable type was developed by:", "options": ["John Locke", "Galileo", "Isaac Newton", "Johannes Gutenberg"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: World History 1$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,2,2,2,2,1,1,1,3,0,1,2,3}'::int[], array[$j$Primary sources come from the period under study.$j$,$j$Corroboration tests whether a source can be trusted.$j$,$j$Constantine dedicated it in 330.$j$,$j$Rome and Constantinople separated.$j$,$j$Muhammad moved from Mecca to Medina in 622.$j$,$j$Baghdad was founded in 762.$j$,$j$Land was granted in exchange for loyalty and service.$j$,$j$It limited the power of King John.$j$,$j$The plague changed European society and economy.$j$,$j$The emperor was a symbol and the shogun ruled.$j$,$j$His gold and generosity were famous.$j$,$j$It stood where Mexico City stands now.$j$,$j$Knotted cords served as records.$j$,$j$He posted the Ninety Five Theses in Wittenberg.$j$,$j$Gutenberg printed his Bible around 1455.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Final Exam: World History 1$j$ on conflict (item_id) do nothing;
end
$seed$;
